    "doc_id": "D06",
    "doc_type": "Employment",
    "summary": "Employee handbook and schedule of senior-staff contracts. Standard terms, two key engineers on six-month notice periods, and no change-of-control bonuses.",
    "red_flags": [
      "Two key engineers have six-month notice periods. This is a key-person retention risk, so the buyer should consider retention arrangements for them."
    ],
    "embedded_instructions_detected": ""
  }
